#include <stdint.h>
#include <string.h>

uint32_t read_len(const unsigned char *buf) {
    /* BUG: buf + 1 is not 4-aligned */
    const uint32_t *p = (const uint32_t *)(buf + 1);
    return *p;
}

uint32_t read_len_ok(const unsigned char *buf) {
    uint32_t v;
    memcpy(&v, buf + 1, sizeof v);  /* any alignment */
    return v;
}
